import type { Metadata } from "next"

// Route generated by app/opengraph-image.tsx. Listed explicitly because a page-level `openGraph` object replaces the root one.
const OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "Aetheria Tech — Practical software products for real business operations" }

export function createPageMetadata({ title, description, path, index = true, absoluteTitle = false }: { title: string; description: string; path: string; index?: boolean; absoluteTitle?: boolean }): Metadata {
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    robots: index ? undefined : { index: false, follow: true },
    openGraph: { type: "website", title, description, url: path, images: [OG_IMAGE] },
    twitter: { card: "summary_large_image", title, description, images: [OG_IMAGE] },
  }
}
